export function translateUi(language: AppLanguage, text: string) {
  return translateDynamicUi(language, text)
    ?? (isTranslationKey(text) ? translate(language, text) : undefined)
    ?? customProfileUiTranslations[language][text]
    ?? customProfileUiTranslations[language][text.trim()]
    ?? uiTranslations[language][text]
    ?? uiTranslations[language][text.trim()]
    ?? addedUiTranslations[language][text]
    ?? addedUiTranslations[language][text.trim()]
    ?? completeUiTranslations[language][text]
    ?? completeUiTranslations[language][text.trim()]
    ?? friendsUiTranslations[language][text]
    ?? friendsUiTranslations[language][text.trim()]
    ?? (language === 'tr' ? text : uiTranslations.en[text] ?? friendsUiTranslations.en[text] ?? text);
}
